import{_ as t,c as o,o as a,ae as i}from"./chunks/framework.CliRSA9F.js";const r="/images/ai_leaderboard.webp",m=JSON.parse('{"title":"AI Leaderboard","description":"","frontmatter":{},"headers":[],"relativePath":"features/ai-leaderboard.md","filePath":"features/ai-leaderboard.md"}'),s={name:"features/ai-leaderboard.md"};function n(l,e,d,c,h,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="ai-leaderboard" tabindex="-1">AI Leaderboard <a class="header-anchor" href="#ai-leaderboard" aria-label="Permalink to &quot;AI Leaderboard&quot;">​</a></h1><h2 id="discover-which-podcasts-ai-platforms-recommend" tabindex="-1">Discover Which Podcasts AI Platforms Recommend <a class="header-anchor" href="#discover-which-podcasts-ai-platforms-recommend" aria-label="Permalink to &quot;Discover Which Podcasts AI Platforms Recommend&quot;">​</a></h2><p>The AI Leaderboard shows you which podcasts are most frequently recommended by major AI assistants across hundreds of topics. Use this data to understand the competitive landscape and identify opportunities to improve your own AI visibility.</p><p><img src="'+r+'" alt="AI Leaderboard Dashboard" width="600px" style="display:block;margin:0 auto;"></p><p><strong>To access</strong>: Navigate to <strong>AI Visibility</strong> in the sidebar, then select the <strong>AI Leaderboards</strong> tab.</p><h2 id="what-you-ll-find" tabindex="-1"><strong>What You&#39;ll Find</strong> <a class="header-anchor" href="#what-you-ll-find" aria-label="Permalink to &quot;**What You&#39;ll Find**&quot;">​</a></h2><p>The AI Leaderboard displays a ranking of podcasts that AI platforms recommend when users ask for podcast suggestions. PodSEO queries four major AI platforms regularly:</p><ul><li><strong>ChatGPT</strong> (OpenAI)</li><li><strong>Claude</strong> (Anthropic)</li><li><strong>Perplexity</strong></li><li><strong>Gemini</strong> (Google)</li></ul><p>The leaderboard shows which podcasts appear most frequently in AI recommendations, giving you insight into what AI considers the &quot;top&quot; podcasts for any given topic.</p><h2 id="how-to-use-the-leaderboard" tabindex="-1"><strong>How to Use the Leaderboard</strong> <a class="header-anchor" href="#how-to-use-the-leaderboard" aria-label="Permalink to &quot;**How to Use the Leaderboard**&quot;">​</a></h2><h3 id="select-a-topic-type" tabindex="-1"><strong>Select a Topic Type</strong> <a class="header-anchor" href="#select-a-topic-type" aria-label="Permalink to &quot;**Select a Topic Type**&quot;">​</a></h3><p>Topics are organized into categories to help you find relevant recommendations:</p><ul><li><strong>Genre</strong> — Podcast categories like Business, True Crime, Comedy, Technology</li><li><strong>Audience</strong> — Target listeners like Entrepreneurs, Parents, Students, Professionals</li><li><strong>Context</strong> — Listening situations like Commute, Workouts, Relaxation, Learning</li><li><strong>Intent</strong> — Listener goals like Entertainment, Education, Inspiration, News</li><li><strong>Format</strong> — Podcast styles like Interview, Solo, Narrative, Panel Discussion</li></ul><p>Each category tab shows how many topics are tracked.</p><h3 id="choose-a-specific-topic" tabindex="-1"><strong>Choose a Specific Topic</strong> <a class="header-anchor" href="#choose-a-specific-topic" aria-label="Permalink to &quot;**Choose a Specific Topic**&quot;">​</a></h3><p>After selecting a topic type, choose a specific topic from the dropdown to see its leaderboard. For example, under &quot;Genre&quot; you might select &quot;Business Podcasts&quot; or &quot;True Crime Podcasts.&quot;</p><h3 id="filter-by-ai-provider" tabindex="-1"><strong>Filter by AI Provider</strong> <a class="header-anchor" href="#filter-by-ai-provider" aria-label="Permalink to &quot;**Filter by AI Provider**&quot;">​</a></h3><p>Use the provider checkboxes to filter which AI platforms you want to include in the rankings. You can:</p><ul><li>View recommendations from all four providers combined</li><li>Focus on a single provider to see its specific recommendations</li><li>Compare how different providers rank the same podcasts</li></ul><h3 id="read-the-leaderboard" tabindex="-1"><strong>Read the Leaderboard</strong> <a class="header-anchor" href="#read-the-leaderboard" aria-label="Permalink to &quot;**Read the Leaderboard**&quot;">​</a></h3><p>Each entry in the leaderboard shows:</p><ul><li><strong>Podcast name and artwork</strong> — The recommended podcast</li><li><strong>Frequency percentage</strong> — How often this podcast appears in AI recommendations (higher is better)</li><li><strong>Provider indicators</strong> — Which specific AI platforms recommend this podcast</li></ul><p>If your podcast appears in the leaderboard, it will be highlighted so you can quickly find your position.</p><h2 id="understanding-frequency" tabindex="-1"><strong>Understanding Frequency</strong> <a class="header-anchor" href="#understanding-frequency" aria-label="Permalink to &quot;**Understanding Frequency**&quot;">​</a></h2><p>AI assistants don&#39;t always give the same answer to the same question — ask one to recommend &quot;the best business podcasts&quot; a few times and the list can change. So a single recommendation isn&#39;t a reliable signal on its own. To account for this, PodSEO asks each topic repeatedly and measures <strong>frequency</strong>: the share of those answers that include a given podcast.</p><p>A podcast with <strong>75% frequency</strong> appears in about three out of four answers for that topic; <strong>100%</strong> means it&#39;s recommended every time. Higher frequency means an assistant reliably associates that podcast with the topic rather than surfacing it now and then — which is why the leaderboard ranks by frequency rather than by whether a podcast was ever mentioned at all.</p><h2 id="strategic-applications" tabindex="-1"><strong>Strategic Applications</strong> <a class="header-anchor" href="#strategic-applications" aria-label="Permalink to &quot;**Strategic Applications**&quot;">​</a></h2><h3 id="competitive-research" tabindex="-1"><strong>Competitive Research</strong> <a class="header-anchor" href="#competitive-research" aria-label="Permalink to &quot;**Competitive Research**&quot;">​</a></h3><p>Use the AI Leaderboard to understand your competitive landscape:</p><ul><li>See which podcasts dominate AI recommendations in your category</li><li>Identify competitors you may not have been aware of</li><li>Understand what topics your competitors are visible for</li></ul><h3 id="topic-opportunity-discovery" tabindex="-1"><strong>Topic Opportunity Discovery</strong> <a class="header-anchor" href="#topic-opportunity-discovery" aria-label="Permalink to &quot;**Topic Opportunity Discovery**&quot;">​</a></h3><p>Find topics where you could potentially gain visibility:</p><ul><li>Browse topics related to your podcast&#39;s content</li><li>Look for topics with less competition</li><li>Identify adjacent topics where your podcast could be relevant</li></ul><h3 id="provider-specific-insights" tabindex="-1"><strong>Provider-Specific Insights</strong> <a class="header-anchor" href="#provider-specific-insights" aria-label="Permalink to &quot;**Provider-Specific Insights**&quot;">​</a></h3><p>Different AI platforms may favor different podcasts:</p><ul><li>Notice which providers recommend which podcasts</li><li>Identify platforms where your competitors are weak</li><li>Understand each provider&#39;s apparent preferences</li></ul><h3 id="track-changes-over-time" tabindex="-1"><strong>Track Changes Over Time</strong> <a class="header-anchor" href="#track-changes-over-time" aria-label="Permalink to &quot;**Track Changes Over Time**&quot;">​</a></h3><p>Regular visits to the leaderboard help you spot trends:</p><ul><li>New podcasts entering the rankings</li><li>Shifts in which podcasts lead specific topics</li><li>Changes in your own podcast&#39;s position</li></ul><h2 id="connection-to-ai-mentions" tabindex="-1"><strong>Connection to AI Mentions</strong> <a class="header-anchor" href="#connection-to-ai-mentions" aria-label="Permalink to &quot;**Connection to AI Mentions**&quot;">​</a></h2><p>The AI Leaderboard shows the broader landscape, while <a href="/features/ai-mentions.html">AI Mentions</a> shows your specific podcast&#39;s performance. Use both together:</p><ol><li>Use <strong>AI Leaderboard</strong> to research topics and competitors</li><li>Use <strong>AI Mentions</strong> to track your own visibility metrics</li><li>Apply insights from both to improve your positioning</li></ol><h2 id="availability" tabindex="-1"><strong>Availability</strong> <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;**Availability**&quot;">​</a></h2><p>The AI Leaderboard is available to all logged-in users. The data updates regularly as PodSEO queries AI platforms for fresh recommendations.</p><hr><h3 id="pro-tips" tabindex="-1"><strong>Pro Tips</strong> <a class="header-anchor" href="#pro-tips" aria-label="Permalink to &quot;**Pro Tips**&quot;">​</a></h3><ul><li>Check <a href="/features/ai-mentions.html">AI Mentions</a> to see your own podcast&#39;s AI visibility metrics</li><li>Use <a href="/features/keyword-strategy.html">Keyword Strategy</a> to optimize for traditional podcast search alongside AI visibility</li><li>Look for topics where the leaderboard has fewer dominant podcasts — these represent easier opportunities to gain AI visibility</li><li>Compare provider-specific rankings to identify where your competitors are strongest and weakest</li></ul>',47)])])}const g=t(s,[["render",n]]);export{m as __pageData,g as default};
